# Apply the rule: unique values replicate to rows where abs(r - feature_row) % 3 == 0
grid = [
    [9, 9, 9, 9, 9, 9, 9, 8, 9],
    [9, 5, 2, 9, 1, 9, 9, 6, 1],
    [3, 9, 9, 9, 9, 9, 9, 6, 9],
    [9, 7, 9, 9, 7, 9, 9, 9, 8],
    [0, 0, 0, 0, 0, 0, 0, 0, 0],
    [9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9]
]

output = [[9]*9 for _ in range(9)]
output[4] = [0]*9  # row 4 stays zeros

# For each column, find unique values and replicate based on period-3 rule
for c in range(9):
    # Find non-9 values in top half and determine feature rows
    seen_values = {}
    for r in range(4):
        v = grid[r][c]
        if v != 9:
            if v not in seen_values:
                seen_values[v] = r  # only track original position for unique values

    # For each unique value, replicate to rows where |r - feature_row| % 3 == 0
    for v, feature_r in seen_values.items():
        for r_test in range(9):
            if r_test != 4:  # don't overwrite separator
                if abs(r_test - feature_r) % 3 == 0:
                    output[r_test][c] = v

print("Period-3 replication from unique values:")
for row in output:
    print(row)

